local hotfix_data = "\t-- 请在此处编写HotFix代码,请组长编写\n\tlocal ActivityUtils = require \"Blueprints.UI.WBP.Activity.ActivityUtils\"\n\tHotFix(ActivityUtils, \"GetCurrentAllActivityWithoutSystemCheck\",\n\t\tfunction( ... )\n\t\t\tlocal AllActivityTabIdx = {}\n\t\t\tlocal CheckIsBanList = {114001, 109001, 103019}\n\t\t\tfor key, TabConfigInfo in pairs(DataMgr.EventTab) do\n\t\t\t\tlocal bIsNeedAddInList = true\n\t\t\t\tif (type(TabConfigInfo.EventId) == \"table\") then\n\t\t\t\t\tfor _, CheckEventId in ipairs(TabConfigInfo.EventId) do\n\t\t\t\t\t\tif CheckEventId == CheckIsBanList[1] or CheckEventId == CheckIsBanList[2] or CheckEventId == CheckIsBanList[3] then\n\t\t\t\t\t\t\tbIsNeedAddInList = false\n\t\t\t\t\t\t\tbreak\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\t\tif bIsNeedAddInList then\n\t\t\t\t\t\tlocal EventConfigData = DataMgr.EventMain[TabConfigInfo.EventId[1]]\n\t\t\t\t\t\tif ActivityUtils.IsComeBackEvent(TabConfigInfo.EventId[1]) then\n\t\t\t\t\t\t\tif ActivityUtils.CheckComeBackEventIsOpen(TabConfigInfo.EventId[1]) then\n\t\t\t\t\t\t\t\ttable.insert(AllActivityTabIdx, TabConfigInfo.EventTabId) -- 还有问题，需要考虑配表回归活动交替时的情况\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\telse\n\t\t\t\t\t\t\tif (ActivityUtils.CheckEventIsOpen(TabConfigInfo.EventId[1], EventConfigData, true, nil)) then\n\t\t\t\t\t\t\t\ttable.insert(AllActivityTabIdx, TabConfigInfo.EventTabId)\n\t\t\t\t\t\t\tend\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\tif TabConfigInfo.EventId == CheckIsBanList[1] or TabConfigInfo.EventId == CheckIsBanList[2] or TabConfigInfo.EventId == CheckIsBanList[3] then\n\t\t\t\t\t\tbIsNeedAddInList = false\n\t\t\t\t\tend\n\t\t\t\t\tif bIsNeedAddInList then\n\t\t\t\t\t\tlocal EventConfigData = DataMgr.EventMain[TabConfigInfo.EventId]\n\t\t\t\t\t\tif (ActivityUtils.CheckEventIsOpen(TabConfigInfo.EventId, EventConfigData, true, nil)) then\n\t\t\t\t\t\t\ttable.insert(AllActivityTabIdx, TabConfigInfo.EventTabId)\n\t\t\t\t\t\tend\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\n\t\t\ttable.sort(AllActivityTabIdx, function(Data1, Data2)\n\t\t\t\tif (DataMgr.EventTab[Data1].Sequence == DataMgr.EventTab[Data2].Sequence) then\n\t\t\t\t\treturn DataMgr.EventTab[Data1].EventTabId < DataMgr.EventTab[Data2].EventTabId\n\t\t\t\telse\n\t\t\t\t\treturn DataMgr.EventTab[Data1].Sequence > DataMgr.EventTab[Data2].Sequence\n\t\t\t\tend\n\t\t\tend)\n\n\t\t\tlocal AllActivityID = {}\n\t\t\tfor _, v in ipairs(AllActivityTabIdx) do\n\t\t\t\tlocal EventConfigData = DataMgr.EventTab[v]\n\t\t\t\tif (type(EventConfigData.EventId) == \"table\") then\n\t\t\t\t\ttable.insert(AllActivityID, EventConfigData.EventId)\n\t\t\t\telse\n\t\t\t\t\ttable.insert(AllActivityID, {EventConfigData.EventId})\n\t\t\t\tend\n\t\t\tend\n\n\t\t\treturn AllActivityID, AllActivityTabIdx\n\t\tend\n\t)\n\t\n\tlocal WBP_Fame_Task_C = require(\"BluePrints.UI.WBP.Fame.WBP_Fame_Task_C\")\n\n\t-- 热更 OnMenuOpenChanged 函数\n\tHotFix(WBP_Fame_Task_C, \"OnMenuOpenChanged\",\n\t    function(self, IsOpen)\n\t        local G = self:Get_G()\n\t        if G.CommonUtils.GetRuntimePlatform(self) == \"Mobile\" then\n\t            return\n\t        end\n\t        if IsOpen then\n\t            self.Com_Tab:UpdateBottomKeyInfo({\n\t                {\n\t                    KeyInfoList = {{Type=\"Text\", Text=\"Esc\", ClickCallback=self.CloseSelf, Owner=self}},\n\t                }\n\t            })\n\t        else\n\t            local NewBottomKeyInfo = {\n\t                {\n\t                    GamePadInfoList = {{Type=\"Img\", ImgShortPath=\"A\", Owner=self}}, Desc=G.GText(\"UI_Tips_Ensure\")\n\t                },\n\t                {\n\t                    KeyInfoList = {{Type=\"Text\", Text=\"Esc\", ClickCallback=self.CloseSelf, Owner=self}},\n\t                    GamePadInfoList = {{Type=\"Img\", ImgShortPath=\"B\", ClickCallback=self.CloseSelf, Owner=self}}, Desc=G.GText(\"UI_BACK\")\n\t                }\n\t            }\n\t            if self.CanQuickClaimIndex and self.CanQuickClaimIndex > 0 then\n\t                G.table.insert(NewBottomKeyInfo, 1, {\n\t                    KeyInfoList = {{Type=\"Text\", Text=\"Space\", ClickCallback=self.QuickClaimCurrentRecurringTask, Owner=self}}, Desc=G.GText(\"UI_BattlePass_QuestRewardClaim\")\n\t                })\n\t            end\n\t            self.Com_Tab:UpdateBottomKeyInfo(NewBottomKeyInfo)\n\t        end\n\t    end\n\t)\n\n\t-- 热更 UpdateQuickClaimButtomTip 函数\n\tHotFix(WBP_Fame_Task_C, \"UpdateQuickClaimButtomTip\",\n\t    function(self)\n\t        local G = self:Get_G()\n\t        if G.CommonUtils.GetRuntimePlatform(self) == \"Mobile\" then\n\t            return\n\t        end\n\t        local NewBottomKeyInfo = {\n\t            {\n\t                GamePadInfoList = {{Type=\"Img\", ImgShortPath=\"A\", Owner=self}}, Desc=G.GText(\"UI_Tips_Ensure\")\n\t            },\n\t            {\n\t                KeyInfoList = {{Type=\"Text\", Text=\"Esc\", ClickCallback=self.CloseSelf, Owner=self}},\n\t                GamePadInfoList = {{Type=\"Img\", ImgShortPath=\"B\", ClickCallback=self.CloseSelf, Owner=self}}, Desc=G.GText(\"UI_BACK\")\n\t            }\n\t        }\n\t        if self.CanQuickClaimIndex and self.CanQuickClaimIndex > 0 then\n\t            G.table.insert(NewBottomKeyInfo, 1, {\n\t                KeyInfoList = {{Type=\"Text\", Text=\"Space\", ClickCallback=self.QuickClaimCurrentRecurringTask, Owner=self}}, Desc=G.GText(\"UI_BattlePass_QuestRewardClaim\")\n\t            })\n\t        end\n\t        self.Com_Tab:UpdateBottomKeyInfo(NewBottomKeyInfo)\n\t    end\n\t)\n\n\t-- 热更 OnKeyDown 函数\n\tHotFix(WBP_Fame_Task_C, \"OnKeyDown\",\n\t    function(self, MyGeometry, InKeyEvent)\n\t        local G = self:Get_G()\n\t        local UE4 = G.UE4\n\t        local IsEventHandled = false\n\t        local InKey = UE4.UKismetInputLibrary.GetKey(InKeyEvent)\n\t        local InKeyName = UE4.UFormulaFunctionLibrary.Key_GetFName(InKey)\n\t        if (UE4.UKismetInputLibrary.Key_IsGamepadKey(InKey)) then\n\t            IsEventHandled = self:Handle_OnGamePadButtonDown(InKeyName)\n\t            if not IsEventHandled then\n\t                IsEventHandled = self.Com_Tab:Handle_KeyEventOnGamePad(InKeyName)\n\t            end\n\t        else\n\t            if G.CommonUtils.GetRuntimePlatform(self) ~= \"Mobile\" then\n\t                IsEventHandled = self.Com_Tab:Handle_KeyEventOnPC(InKeyName)\n\t            else\n\t                IsEventHandled = self.Com_Tab:Handle_KeyEventOnTouch(InKeyName)\n\t            end\n\t            if not IsEventHandled then\n\t                IsEventHandled = self:Handle_OnPCButtonDown(InKeyName)\n\t            end\n\t        end\n\t        if (IsEventHandled) then\n\t            return UE4.UWidgetBlueprintLibrary.Handled()\n\t        else\n\t            return UE4.UWidgetBlueprintLibrary.UnHandled()\n\t        end\n\t    end\n\t)\n\n\n\tConst.ProgressRecoverDungeonType.Survival = false\n\tConst.ProgressRecoverDungeonType.SurvivalPro = false\n\tConst.ProgressRecoverDungeonType.SurvivalMini = false\n\tConst.ProgressRecoverDungeonType.Defence = false\n\tConst.ProgressRecoverDungeonType.Excavation = false\n\n\n"
